for i in 1 2 3 4 5 6 7 8; do ./gradlew assembleDebug --no-daemon > out.log 2>&1; rc=$?; [ $rc -eq 0 ] && break; miss=$(grep -oE "resource drawable/[A-Za-z0-9_]+" out.log | sed "s#resource drawable/##" | sort -u); [ -z "$miss" ] && break; for n in $miss; do echo '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24"><path android:fillColor="#FFFFFFFF" android:pathData="M12,2L2,22h20z"/></vector>' > app/src/main/res/drawable/$n.xml; done; done; grep -E "error|FAILED|BUILD" out.log | head -30; exit $rc
